import java.io.File;
import java.io.IOException;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a new {@link File} inside {@code dir} with a name derived from {@code name}.
     * The method protects against directory‑traversal attacks by ensuring that the
     * resolved canonical path of the resulting file is a sub‑path of {@code dir}.
     *
     * @param dir  the base directory where the file should be created
     * @param name the requested file name (may contain query parameters)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if {@code dir} or {@code name} is null,
     *                                  empty, or would resolve outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        if (name.isEmpty()) {
            throw new IllegalArgumentException("Name must not be empty");
        }

        // Reject absolute paths – they would ignore the supplied directory
        if (new File(name).isAbsolute()) {
            throw new IllegalArgumentException("Absolute paths are not allowed");
        }

        // Prevent path traversal by normalizing and checking containment
        File candidate = new File(dir, name);
        try {
            File canonicalDir = dir.getCanonicalFile();
            File canonicalCandidate = candidate.getCanonicalFile();

            String dirPath = canonicalDir.getPath();
            String candidatePath = canonicalCandidate.getPath();

            // Ensure the candidate is within the directory tree
            if (!candidatePath.startsWith(dirPath + File.separator)
                    && !candidatePath.equals(dirPath)) {
                throw new IllegalArgumentException(
                        "Attempt to create file outside the allowed directory");
            }
        } catch (IOException e) {
            throw new IllegalArgumentException("Failed to resolve canonical paths", e);
        }

        // Resolve name collisions by appending a numeric suffix
        String baseName = name;
        int dotIndex = name.lastIndexOf('.');
        String prefix = (dotIndex < 0) ? name : name.substring(0, dotIndex);
        String suffix = (dotIndex < 0) ? "" : name.substring(dotIndex);
        int index = 2;
        File file = candidate;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Ensure parent directories exist
        file.getParentFile().mkdirs();
        return file;
    }

