    @Override
    public ByteBuffer encode(final String name) {
        final CharsetEncoder enc = newEncoder();
        final CharBuffer cb = CharBuffer.wrap(name);
        CharBuffer tmp = null;
        ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

        /* Maximum number of times we allow a single character to trigger an error
           before giving up. This protects against malicious input that could
           otherwise cause an infinite loop. */
        final int MAX_ERROR_RETRIES = 10;
        int errorRetryCount = 0;

        while (cb.hasRemaining()) {
            final CoderResult res = enc.encode(cb, out, false);

            if (res.isError()) {
                /* Ensure we make progress by consuming the problematic
                   character(s). If the error length is zero (which should
                   not happen), consume one character to avoid a stall. */
                int errLen = res.length();
                if (errLen <= 0) {
                    errLen = 1;
                }

                /* Prevent endless looping on malformed/unmappable input. */
                if (++errorRetryCount > MAX_ERROR_RETRIES) {
                    throw new CharacterCodingException();
                }

                /* Grow the output buffer if necessary to accommodate the
                   surrogate replacement. */
                int spaceForSurrogate = estimateIncrementalEncodingSize(enc, 6 * errLen);
                if (spaceForSurrogate > out.remaining()) {
                    int charCount = 0;
                    for (int i = cb.position(); i < cb.limit(); i++) {
                        charCount += !enc.canEncode(cb.get(i)) ? 6 : 1;
                    }
                    int totalExtraSpace = estimateIncrementalEncodingSize(enc, charCount);
                    out = ZipEncodingHelper.growBufferBy(out, totalExtraSpace - out.remaining());
