    /**
     * Creates an {@link LdapContext} that authenticates using STARTTLS.
     *
     * <p>This method now performs the following steps in order to guarantee that
     * credentials are transmitted over a protected channel and that the LDAP
     * server actually validates them:
     *
     * <ol>
     *   <li>Validate that {@code principal} and {@code credentials} are non‑null.</li>
     *   <li>Create a context without credentials so that the connection is
     *       initially anonymous.</li>
     *   <li>Negotiate STARTTLS to upgrade the connection to TLS.</li>
     *   <li>Re‑bind (reconnect) with the supplied credentials over the TLS
     *       session.</li>
     * </ol>
     *
     * @param ldapContextFactory the factory providing LDAP configuration
     * @param principal          the user DN or bind name
     * @param credentials        the user password
     * @return an authenticated {@link LdapContext}
     * @throws NamingException if the connection or authentication fails
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                    Object principal,
                                                    Object credentials) throws NamingException {
        if (principal == null || credentials == null) {
            throw new IllegalArgumentException("Principal and credentials must not be null");
        }

        JndiLdapContextFactory jndiFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> baseEnv = new Hashtable<>();
        baseEnv.put(Context.INITIAL_CONTEXT_FACTORY, jndiFactory.getContextFactoryClassName());
        baseEnv.put(Context.PROVIDER_URL, jndiFactory.getUrl());

        LdapContext ctx = null;
        StartTlsResponse tls = null;

        try {
            // 1. Create an anonymous context
            ctx = new InitialLdapContext(baseEnv, null);

            // 2. Negotiate STARTTLS
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate(); // throws IOException on failure

            // 3. Prepare environment with credentials
            Hashtable<String, Object> authEnv = new Hashtable<>(baseEnv);
            authEnv.put(Context.SECURITY_AUTHENTICATION, jndiFactory.getAuthenticationMechanism());
            authEnv.put(Context.SECURITY_PRINCIPAL, principal);
            authEnv.put(Context.SECURITY_CREDENTIALS, credentials);

            // 4. Re‑bind over the TLS session
            ctx.reconnect(authEnv);

            return ctx;
        } catch (IOException ioe) {
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': %s",
                    server(jndiFactory), ioe.getMessage()), ioe);
            throw new CommunicationException(ioe.getMessage(), ioe);
        } catch (NamingException ne) {
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to authenticate with '%s': %s",
                    server(jndiFactory), ne.getMessage()), ne);
            throw ne;
        } catch (Throwable t) {
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Unexpected failure to negotiate TLS connection with '%s': %s",
                    server(jndiFactory), t.getMessage()), t);
