import java.io.InputStream;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.TransformerConfigurationException;
import javax.xml.transform.stream.StreamSource;
import javax.xml.XMLConstants;
import java.io.IOException;

/**
 * Renderer implementation that safely compiles XSLT templates.
 */
public class XsltRenderer implements Renderer {

    // No shared TransformerFactory – each call creates a fresh, securely configured instance.
    // This avoids accidental leakage of configuration between threads and ensures
    // that security settings are applied consistently.
    private static TransformerFactory newSecureTransformerFactory() {
        TransformerFactory factory = TransformerFactory.newInstance();
        try {
            // Enable the standard secure processing feature to prevent
            // potentially dangerous extensions and external resource access.
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Explicitly deny access to external DTDs and stylesheets.
            // Setting the attributes to an empty string disables all external
            // entity resolution, mitigating XXE and XSLT-based RCE attacks.
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
        } catch (IllegalArgumentException | UnsupportedOperationException e) {
            // If the underlying implementation does not support the feature/attribute,
            // log the issue and proceed with the default configuration.
            // In production, replace System.err with a proper logging framework.
            System.err.println("Failed to enable secure XSLT processing: " + e.getMessage());
        }
        return factory;
    }

    // other methods

    /**
     * Creates a {@link Transformer} from the supplied XSLT template stream.
     *
     * @param templateStream the XSLT template as an {@link InputStream}. Must not be {@code null}.
     * @return a securely configured {@link Transformer}
     * @throws IOException if the stream cannot be read or closed
     * @throws ProcessingFailedException if the XSLT is malformed or cannot be compiled
     */
    private static Transformer createTransformer(InputStream templateStream)
            throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("templateStream must not be null");
        }

        // Use a fresh, securely configured factory for each invocation.
        TransformerFactory factory = newSecureTransformerFactory();

        try {
            // The StreamSource consumes the stream; it will be closed in the finally block.
            return factory.newTransformer(new StreamSource(templateStream));
        } catch (TransformerConfigurationException e) {
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        } finally {
            // Ensure the caller's stream is closed to avoid resource leaks.
            templateStream.close();
        }
    }

    // other methods

