     * @param supplier   provides the next readable archive entry
     * @param writer     writes the entry data to an output stream
     * @param targetDirectory the directory into which the archive is extracted
     * @throws IOException if an I/O error occurs or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical path of the target directory once.
        Path targetDirPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            String entryName = nextEntry.getName();

            // Basic sanity checks on the entry name.
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has empty name");
            }
            // Reject absolute paths, drive letters, and any attempt to escape the target dir.
            if (entryName.contains("..") ||
                entryName.startsWith("/") ||
                entryName.startsWith("\\") ||
                entryName.contains(":")) {
                throw new IOException("invalid entry name: " + entryName);
            }

            // Resolve the entry against the target directory and normalize.
            Path resolvedPath = targetDirPath.resolve(entryName).normalize();

            // Ensure the resolved path is still under the target directory.
            if (!resolvedPath.startsWith(targetDirPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            File f = resolvedPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!f.isDirectory() && !f.mkdirs()) {
                    throw new IOException("failed to create directory " + f);
                }
            } else {
                // Ensure parent directories exist.
                Path parentPath = resolvedPath.getParent();
                if (parentPath != null && !Files.exists(parentPath)) {
                    Files.createDirectories(parentPath);
                }

                // Write the file contents.
                try (OutputStream out = Files.newOutputStream(resolvedPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

