    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // other methods

    /**
     * Converts a {@link StreamSource} into a {@link SAXSource} while protecting
     * against XML External Entity (XXE) attacks. The method explicitly disables
     * external entity resolution and DTD processing by configuring the
     * {@link SAXParserFactory} and the underlying {@link XMLReader} with the
     * recommended security features.
     *
     * @param source   the source XML stream
     * @param exchange optional Camel exchange that may contain a pre‑configured
     *                 {@link SAXParserFactory}
     * @return a secure {@link SAXSource}
     * @throws SAXException if the parser cannot be created or configured
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else {
            inputSource = new InputSource(source.getInputStream());
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        SAXParserFactory sfactory = null;
        XMLReader xmlReader = null;

        try {
            // Reuse a factory from the exchange if available
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            // Enable secure processing
            enableFeature(sfactory, XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Disable DTDs entirely
            enableFeature(sfactory, "http://apache.org/xml/features/disallow-doctype-decl", true);

            // Prevent external entity resolution
            enableFeature(sfactory, "http://xml.org/sax/features/external-general-entities", false);
            enableFeature(sfactory, "http://xml.org/sax/features/external-parameter-entities", false);

            // Avoid loading external DTDs or grammar
            enableFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            enableFeature(sfactory, "http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);

            // Optional: disable validation to reduce overhead
            sfactory.setValidating(false);
            sfactory.setNamespaceAware(true);

            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Additional safety checks on the XMLReader
            enableReaderFeature(xmlReader, "http://apache.org/xml/features/disallow-doctype-decl", true);
            enableReaderFeature(xmlReader, "http://xml.org/sax/features/external-general-entities", false);
            enableReaderFeature(xmlReader, "http://xml.org/sax/features/external-parameter-entities", false);
        } catch (Exception e) {
            LOG.warn("Failed to create a secure SAXParser/XMLReader: {}", e.toString(), e);
            throw new SAXException("Unable to configure secure XML parser", e);
        }

        return new SAXSource(xmlReader, inputSource);
    }

    /**
     * Helper to set a feature on a {@link SAXParserFactory} with graceful
     * handling of unsupported features.
     */
    private void enableFeature(SAXParserFactory factory, String feature, boolean value) {
        try {
            factory.setFeature(feature, value);
        } catch (Exception e) {
            LOG.warn("SAXParserFactory does not support feature {} with value {}: {}", feature, value, e.toString());
        }
    }

    /**
     * Helper to set a feature on an {@link XMLReader} with graceful
     * handling of unsupported features.
     */
    private void enableReaderFeature(XMLReader reader, String feature, boolean value) {
        try {
            reader.setFeature(feature, value);
        } catch (SAXException e) {
            LOG.warn("XMLReader does not support feature {} with value {}: {}", feature, value, e.toString());
        }
    }

    // other methods
}
